import math

n = int(input())
du_lieu = []
for _ in range(n):
    nhan, noi_dung = input().split("|")
    du_lieu.append((nhan, noi_dung.split()))
tin = input().split()

so_tin = {"spam": 0, "ham": 0}
dem_tu = {"spam": {}, "ham": {}}
tong_tu = {"spam": 0, "ham": 0}
V = set()
for nhan, tu in du_lieu:
    so_tin[nhan] += 1
    for w in tu:
        dem_tu[nhan][w] = dem_tu[nhan].get(w, 0) + 1
        tong_tu[nhan] += 1
        V.add(w)

diem = {}
for c in ("spam", "ham"):
    s = math.log(so_tin[c] / n)
    for w in tin:
        if w in V:
            s += math.log((dem_tu[c].get(w, 0) + 1) / (tong_tu[c] + len(V)))
    diem[c] = s
print("spam" if diem["spam"] > diem["ham"] else "ham")
